 void geometry(Activity a,List<View> buttons,String name){for(View v:buttons){if(!v.isEnabled())continue;main(()->{v.requestFocus();return null;});SystemClock.sleep(550);main(()->{Rect visible=new Rect();Matrix matrix=new Matrix();v.transformMatrixToGlobal(matrix);RectF expected=new RectF(0,0,v.getWidth(),v.getHeight());matrix.mapRect(expected);boolean shown=v.getGlobalVisibleRect(visible);boolean fits=shown&&expected.left>=visible.left-2&&expected.top>=visible.top-2&&expected.right<=visible.right+2&&expected.bottom<=visible.bottom+2;record(name+" focused edge: "+(v instanceof TextView?((TextView)v).getText():"card"),fits,"expected="+expected+" visible="+visible);if(!fits)throw new AssertionError(name+" focused bounds");return null;});}}
